Definition recycle_sec1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo a TH : Z)
    : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (AINST + 64)) (wz (AINST + 688)) (wz (a + 4096)) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x52998) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 80, bv_unsigned sp); (1221632, 1221636); (TH + 2840, TH + 2856)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' 1221632 [C8 (wz 0)]
    /\ stk bsegs m' (TH + 2800) (TH + 3168).

Section Rec1.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo a msz sz idx pa nres nch srt TSD CTX TH sb n actx : Z) (chunks : list Z) (ob0 ob1 : byte).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 80 <= bv_unsigned sp.
  Hypothesis Ha1 : a1 = wz (a + 6128).
  Hypothesis AR : aapp a msz /\ a + msz <= aceil /\ a mod 4096 = 0 /\ 0x2000 <= msz.
  Hypothesis SBX : hidden (a + msz <= sb \/ sb + kSpaceSize <= a).
  Hypothesis SBR : hidden (AHI_LO <= sb /\ sb + kSpaceSize <= aceil).
  Hypothesis TPR : hidden (6354696 <= bv_unsigned tp /\ bv_unsigned tp + 4096 <= AIMG_TOP).
  Hypothesis RNG : hidden (6354608 <= TSD /\ TSD + 8 <= AIMG_TOP /\ aapp CTX 160 /\ CTX + 160 <= aceil /\ akobj TH 4096 /\ TH + 4096 <= aceil /\ TH mod 16 = 0).
  Hypothesis PLC : hidden ((CTX + 160 <= TH \/ TH + 4096 <= CTX) /\ (TH + 4096 <= a \/ a + msz <= TH) /\ (CTX + 160 <= a \/ a + msz <= CTX)).
  Hypothesis PAR : aapp pa (8 * nch) /\ pa + 8 * nch <= aceil.
  Hypothesis NCH : zlen chunks = nch /\ 1 <= nch.
  Hypothesis INA : In a chunks.
  Hypothesis DISJ : Forall (fun c => 0 <= c < 2^47 /\ (c <= a + 6128 -> c <= a)) chunks.
  Hypothesis NR : 0 <= n < 2^32.
  Hypothesis ENV : SENV tp TSD CTX TH m.
  Hypothesis SB32 : rw_cells bsegs m (AINST + 32) [C8 (wz sb)].
  Hypothesis INST64 : rw_cells bsegs m (AINST + 64) [C8 (wz 4096); C8 (wz pa); C8 (wz pa)].
  Hypothesis NRES : rw_cells bsegs m (AINST + 112) [C8 (wz nres); C8 (wz nch); C8 (wz srt)].
  Hypothesis MTX : rw_cells bsegs m (AINST + 680) [C8 (wz 0)].
  Hypothesis PA : u64arr bsegs m pa (wlist chunks).
  Hypothesis HDR : rw_cells bsegs m a [C8 (wz a); C8 (wz msz); C8 (wz sz); C8 (wz idx)].
  Hypothesis CHDR : rw_cells bsegs m (a + 6128) [C1 ob0; C1 ob1; C2 (wz 0); C4 (wz n); C8 (wz actx)].
  Hypothesis TST : stk bsegs m (TH + 2800) (TH + 3168).

  (* [comment removed for export] *)
  Let ARE : 6832128 <= a /\ a + msz <= aceil. Proof. exact (aapp_env _ _ (proj1 AR) ltac:(lia)). Qed.   (* [comment removed for export] *)
  Let PAE : 6832128 <= pa /\ pa + 8 * nch <= aceil. Proof. exact (aapp_env _ _ (proj1 PAR) ltac:(lia)). Qed.
